#include "../include/bonsai_kg_v4.hpp"
#include "../include/bonsai_kg_v4_io.hpp"
#include <cuda_runtime.h>
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace bonsaikg4;
struct BenchObs4{int step=0;__host__ __device__ inline int32_t feature(uint16_t id,int32_t a0=0,int32_t a1=0)const{(void)a0;(void)a1;if(id==F_STEP)return step;if(id==F_DAY)return step/24;if(id==F_HOUR)return step%24;if(id==F_OWN_UNITS)return 1;return 0;}};
static void ck(cudaError_t e,const char*w){if(e!=cudaSuccess)throw std::runtime_error(std::string(w)+": "+cudaGetErrorString(e));}template<class T>T*cp(const std::vector<T>&v){if(v.empty())return nullptr;T*d=nullptr;ck(cudaMalloc((void**)&d,v.size()*sizeof(T)),"malloc table");ck(cudaMemcpy(d,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice),"copy table");return d;}
struct D{Node4*n=nullptr;uint16_t*c=nullptr;BbDecl4*b=nullptr;ValueRef4*v=nullptr;FeatureArgRef4*a=nullptr;Predicate4*q=nullptr;Lifecycle4*l=nullptr;Effect4*e=nullptr;~D(){if(n)cudaFree(n);if(c)cudaFree(c);if(b)cudaFree(b);if(v)cudaFree(v);if(a)cudaFree(a);if(q)cudaFree(q);if(l)cudaFree(l);if(e)cudaFree(e);}};
template<int IC,int DC>__global__ void bench4(PolicyView4 p,int32_t*bb,NodeState4*ns,RuntimeMeta4*m,int iters,uint32_t*out){int id=blockIdx.x*blockDim.x+threadIdx.x;RuntimeView4 st{p.n_bb?bb+(size_t)id*p.n_bb:nullptr,p.n_state?ns+(size_t)id*p.n_state:nullptr,m+id};reset_runtime(p,st);uint32_t z=0;for(int i=0;i<iters;++i){BenchObs4 o{i};ActionResult4 a{};Status r=tick_specialized4<BenchObs4,IC,DC>(p,st,o,10,a,nullptr);z+=(uint32_t)r+(uint32_t)a.n_market+(uint32_t)a.units[0].op;}out[id]=z+m[id].ticks;}
template<int IC,int DC>void launch(PolicyView4 p,int32_t*bb,NodeState4*ns,RuntimeMeta4*m,int envs,int it,uint32_t*out){bench4<IC,DC><<<(envs+127)/128,128>>>(p,bb,ns,m,it,out);}
#define CASE(IC,DC) if(ic==IC&&dc==DC){launch<IC,DC>(p,bb,ns,m,envs,it,out);return;}
static void dispatch(int ic,int dc,PolicyView4 p,int32_t*bb,NodeState4*ns,RuntimeMeta4*m,int envs,int it,uint32_t*out){CASE(0,16)CASE(0,24)CASE(0,32)CASE(0,48)CASE(8,16)CASE(8,24)CASE(8,32)CASE(8,48)CASE(16,16)CASE(16,24)CASE(16,32)CASE(16,48)CASE(32,16)CASE(32,24)CASE(32,32)CASE(32,48)CASE(64,16)CASE(64,24)CASE(64,32)CASE(64,48)CASE(128,16)CASE(128,24)CASE(128,32)CASE(128,48)throw std::runtime_error("bad specialization");}
#undef CASE
struct ResourceInfo{int regs=0;size_t local_bytes=0;int blocks_per_sm=0;};
template<int IC,int DC>static ResourceInfo resource_one(){cudaFuncAttributes a{};ck(cudaFuncGetAttributes(&a,bench4<IC,DC>),"func attrs");int blocks=0;ck(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks,bench4<IC,DC>,128,0),"occupancy");return {a.numRegs,a.localSizeBytes,blocks};}
#define RCASE(IC,DC) if(ic==IC&&dc==DC)return resource_one<IC,DC>();
static ResourceInfo resources(int ic,int dc){RCASE(0,16)RCASE(0,24)RCASE(0,32)RCASE(0,48)RCASE(8,16)RCASE(8,24)RCASE(8,32)RCASE(8,48)RCASE(16,16)RCASE(16,24)RCASE(16,32)RCASE(16,48)RCASE(32,16)RCASE(32,24)RCASE(32,32)RCASE(32,48)RCASE(64,16)RCASE(64,24)RCASE(64,32)RCASE(64,48)RCASE(128,16)RCASE(128,24)RCASE(128,32)RCASE(128,48)throw std::runtime_error("bad specialization");}
#undef RCASE
static int intent_class(int n){return n==0?0:n<=8?8:n<=16?16:n<=32?32:n<=64?64:128;}static int depth_class(int n){return n<=16?16:n<=24?24:n<=32?32:48;}
int main(int argc,char**argv){try{if(argc<2||argc>5)throw std::runtime_error("usage: v4_benchmark POLICY [CPU_ITERS] [GPU_ENVS] [GPU_ITERS]");int cpu=argc>2?std::atoi(argv[2]):200000,envs=argc>3?std::atoi(argv[3]):8192,it=argc>4?std::atoi(argv[4]):64;auto owned=load_compiled4(argv[1]);PolicyView4 hp=owned.view();std::vector<int32_t>hbb(hp.n_bb);std::vector<NodeState4>hns(hp.n_state);RuntimeMeta4 hm{};RuntimeView4 hs{hbb.data(),hns.data(),&hm};reset_runtime(hp,hs);uint64_t sum=0;auto t0=std::chrono::steady_clock::now();for(int i=0;i<cpu;++i){BenchObs4 o{i};ActionResult4 a{};auto r=tick4(hp,hs,o,10,a,nullptr);sum+=(unsigned)r+(unsigned)a.n_market;}double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count();D d;d.n=cp(owned.nodes);d.c=cp(owned.child_refs);d.b=cp(owned.bb);d.v=cp(owned.values);d.a=cp(owned.feature_args);d.q=cp(owned.predicates);d.l=cp(owned.lifecycles);d.e=cp(owned.effects);PolicyView4 p=hp;p.nodes=d.n;p.child_refs=d.c;p.bb=d.b;p.values=d.v;p.feature_args=d.a;p.predicates=d.q;p.lifecycles=d.l;p.effects=d.e;int32_t*bb=nullptr;NodeState4*ns=nullptr;RuntimeMeta4*m=nullptr;uint32_t*out=nullptr;if(hp.n_bb)ck(cudaMalloc((void**)&bb,(size_t)envs*hp.n_bb*sizeof(int32_t)),"bb");if(hp.n_state)ck(cudaMalloc((void**)&ns,(size_t)envs*hp.n_state*sizeof(NodeState4)),"ns");ck(cudaMalloc((void**)&m,(size_t)envs*sizeof(RuntimeMeta4)),"meta");ck(cudaMalloc((void**)&out,(size_t)envs*sizeof(uint32_t)),"out");int ic=intent_class(hp.max_live_intents),dc=depth_class(hp.max_depth);cudaEvent_t a,b;ck(cudaEventCreate(&a),"event");ck(cudaEventCreate(&b),"event");ck(cudaEventRecord(a),"record");dispatch(ic,dc,p,bb,ns,m,envs,it,out);ck(cudaGetLastError(),"launch");ck(cudaEventRecord(b),"record2");ck(cudaEventSynchronize(b),"sync");float ms=0;ck(cudaEventElapsedTime(&ms,a,b),"elapsed");const double ticks=(double)envs*it;const size_t runtime_bytes=(size_t)hp.n_bb*4+(size_t)hp.n_state*8+sizeof(RuntimeMeta4);ResourceInfo ri=resources(ic,dc);cudaDeviceProp prop{};ck(cudaGetDeviceProperties(&prop,0),"device props");double occ=(double)ri.blocks_per_sm*128.0/(double)prop.maxThreadsPerMultiProcessor;
 std::cout<<"nodes="<<hp.n_nodes<<" state="<<hp.n_state<<" bb="<<hp.n_bb<<" depth="<<hp.max_depth<<" depth_class="<<dc<<" live="<<hp.max_live_intents<<" intent_class="<<ic<<" budget="<<hp.instruction_budget<<" cpu_ticks_s="<<(cpu/sec)<<" cpu_ns_tick="<<(sec*1e9/cpu)<<" cpu_checksum="<<sum<<" gpu_envs="<<envs<<" gpu_iters="<<it<<" gpu_ms="<<ms<<" gpu_ticks_s="<<(ticks/(ms/1000.0))<<" runtime_bytes_env="<<runtime_bytes<<" regs="<<ri.regs<<" local_bytes="<<ri.local_bytes<<" blocks_per_sm="<<ri.blocks_per_sm<<" occupancy_threads_fraction="<<occ<<"\n";if(bb)cudaFree(bb);if(ns)cudaFree(ns);cudaFree(m);cudaFree(out);cudaEventDestroy(a);cudaEventDestroy(b);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
